-- =====================================================
-- SKEMA BASIS DATA
-- SISTEM REKOMENDASI DESAIN UNDANGAN - PERCETAKAN ROTAMA JAYA
-- =====================================================

CREATE DATABASE IF NOT EXISTS rotama_jaya CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE rotama_jaya;

-- Tabel admin (satu-satunya pengguna yang mengoperasikan sistem)
CREATE TABLE admin (
    id_admin INT AUTO_INCREMENT PRIMARY KEY,
    nama_admin VARCHAR(100) NOT NULL,
    nama_pengguna VARCHAR(50) NOT NULL UNIQUE,
    kata_sandi VARCHAR(255) NOT NULL,
    peran ENUM('admin') NOT NULL DEFAULT 'admin',
    dibuat_pada DATETIME DEFAULT CURRENT_TIMESTAMP
);

-- Tabel kategori desain undangan
CREATE TABLE kategori_desain (
    id_kategori INT AUTO_INCREMENT PRIMARY KEY,
    nama_kategori VARCHAR(50) NOT NULL
);

-- Tabel utama desain undangan
CREATE TABLE desain_undangan (
    id_desain INT AUTO_INCREMENT PRIMARY KEY,
    id_kategori INT,
    tema ENUM('elegan','floral','modern','minimalis','islami','adat_batak') NULL,
    judul_desain VARCHAR(150) NOT NULL,
    deskripsi_desain TEXT,
    kata_kunci TEXT COMMENT 'Sumber teks untuk TF-IDF',
    nama_file_gambar VARCHAR(255) NOT NULL COMMENT 'Path gambar pratinjau publik',
    nama_file_webp VARCHAR(255) NULL COMMENT 'Path versi WebP terkompresi untuk web',
    nama_file_produksi VARCHAR(255) COMMENT 'Path file PSD/CDR, khusus admin',
    status_proses ENUM('diproses','siap','gagal') NOT NULL DEFAULT 'siap' COMMENT 'Status pemrosesan fitur AI untuk desain',
    vektor_fitur_cnn LONGTEXT COMMENT 'Vektor fitur CNN MobileNetV2 (JSON array)',
    vektor_fitur_tfidf LONGTEXT COMMENT 'Vektor fitur TF-IDF (JSON array)',
    diunggah_oleh INT,
    dibuat_pada DATETIME DEFAULT CURRENT_TIMESTAMP,
    INDEX idx_desain_dibuat_pada (dibuat_pada),
    INDEX idx_desain_kategori_dibuat_pada (id_kategori, dibuat_pada),
    FOREIGN KEY (id_kategori) REFERENCES kategori_desain(id_kategori),
    FOREIGN KEY (diunggah_oleh) REFERENCES admin(id_admin)
);

-- Tabel riwayat pencarian (opsional, untuk analisis)
CREATE TABLE riwayat_pencarian (
    id_riwayat INT AUTO_INCREMENT PRIMARY KEY,
    id_admin INT NULL COMMENT 'Admin yang melakukan pencarian',
    jenis_pencarian ENUM('gambar','teks') NOT NULL,
    kata_kunci_dicari TEXT,
    nama_file_dicari VARCHAR(255),
    waktu_proses_ms DECIMAL(10,3),
    dicari_pada DATETIME DEFAULT CURRENT_TIMESTAMP,
    INDEX idx_riwayat_jenis_waktu (jenis_pencarian, dicari_pada),
    FOREIGN KEY (id_admin) REFERENCES admin(id_admin)
);

-- Kategori yang muncul pada hasil setiap pencarian.
-- Satu pencarian dapat memiliki beberapa kategori hasil rekomendasi.
CREATE TABLE riwayat_pencarian_kategori (
    id_riwayat_kategori INT AUTO_INCREMENT PRIMARY KEY,
    id_riwayat INT NOT NULL,
    id_kategori INT NOT NULL,
    jumlah_hasil INT NOT NULL DEFAULT 0,
    UNIQUE KEY uq_riwayat_kategori (id_riwayat, id_kategori),
    FOREIGN KEY (id_riwayat) REFERENCES riwayat_pencarian(id_riwayat) ON DELETE CASCADE,
    FOREIGN KEY (id_kategori) REFERENCES kategori_desain(id_kategori) ON DELETE CASCADE,
    INDEX idx_riwayat_kategori_kategori (id_kategori)
);

-- Tabel hasil pengujian CNN MobileNetV2
CREATE TABLE pengujian_cnn (
    id_pengujian INT AUTO_INCREMENT PRIMARY KEY,
    nomor_skenario INT NOT NULL UNIQUE,
    nama_gambar_uji VARCHAR(255),
    presisi_5 DECIMAL(5,4),
    presisi_10 DECIMAL(5,4),
    ingatan_5 DECIMAL(5,4),
    ingatan_10 DECIMAL(5,4),
    skor_f1_5 DECIMAL(5,4),
    skor_f1_10 DECIMAL(5,4),
    dicatat_pada DATETIME DEFAULT CURRENT_TIMESTAMP
);

-- Tabel hasil pengujian TF-IDF + Kesamaan Kosinus
CREATE TABLE pengujian_tfidf (
    id_pengujian INT AUTO_INCREMENT PRIMARY KEY,
    nomor_skenario INT NOT NULL UNIQUE,
    kata_kunci_uji VARCHAR(255),
    presisi_5 DECIMAL(5,4),
    presisi_10 DECIMAL(5,4),
    ingatan_5 DECIMAL(5,4),
    ingatan_10 DECIMAL(5,4),
    skor_f1_5 DECIMAL(5,4),
    skor_f1_10 DECIMAL(5,4),
    dicatat_pada DATETIME DEFAULT CURRENT_TIMESTAMP
);

-- Tabel pesanan
-- Admin membuat pesanan langsung saat pelanggan datang ke toko.
-- Tidak ada akun pelanggan; nama dan telepon diisi langsung oleh admin.
CREATE TABLE pesanan (
    id_pesanan INT AUTO_INCREMENT PRIMARY KEY,
    id_desain INT NULL COMMENT 'Desain yang dipilih dari hasil rekomendasi',
    nama_pelanggan VARCHAR(100) NOT NULL COMMENT 'Nama pelanggan yang datang ke toko',
    nomor_telepon VARCHAR(20) NULL COMMENT 'Nomor HP pelanggan',
    jumlah INT NOT NULL DEFAULT 1 COMMENT 'Jumlah undangan yang dicetak (lembar)',
    status ENUM('menunggu_dp','diproses','selesai') NOT NULL DEFAULT 'menunggu_dp',
    jumlah_dp DECIMAL(12,2) DEFAULT 0 COMMENT 'DP yang diterima (diperbarui admin)',
    teks_desain TEXT NULL COMMENT 'Teks personalisasi: nama, tanggal, dll dari pelanggan',
    foto_pelanggan VARCHAR(255) NULL COMMENT 'Foto dari pelanggan untuk dimasukkan ke desain',
    catatan TEXT NULL COMMENT 'Catatan tambahan admin',
    dibuat_oleh INT NULL COMMENT 'Admin yang membuat pesanan',
    dibuat_pada DATETIME DEFAULT CURRENT_TIMESTAMP,
    diperbarui_pada DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    INDEX idx_pesanan_status (status),
    INDEX idx_pesanan_dibuat_pada (dibuat_pada),
    FOREIGN KEY (id_desain) REFERENCES desain_undangan(id_desain),
    FOREIGN KEY (dibuat_oleh) REFERENCES admin(id_admin)
);

-- Tabel log aktivitas admin (audit trail sederhana)
-- Mencatat siapa melakukan apa: ubah status pesanan, hapus desain, ubah kategori,
-- kelola akun admin, dll. Tidak menyimpan nilai sensitif (mis. kata sandi baru).
CREATE TABLE log_aktivitas (
    id_log INT AUTO_INCREMENT PRIMARY KEY,
    id_admin INT NULL COMMENT 'Admin yang melakukan aksi (NULL jika akun sudah dihapus)',
    nama_admin_saat_itu VARCHAR(100) NOT NULL COMMENT 'Disalin saat aksi terjadi, supaya riwayat tetap terbaca walau akun admin kemudian dihapus',
    modul VARCHAR(30) NOT NULL COMMENT 'pesanan | desain | kategori | admin | pengaturan',
    aksi VARCHAR(30) NOT NULL COMMENT 'tambah | ubah | hapus | login | dll',
    keterangan TEXT NOT NULL COMMENT 'Deskripsi singkat, sudah dalam bahasa manusia, siap ditampilkan',
    dicatat_pada DATETIME DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (id_admin) REFERENCES admin(id_admin) ON DELETE SET NULL,
    INDEX (dicatat_pada),
    INDEX (modul)
);

-- Akun default
INSERT INTO admin (nama_admin, nama_pengguna, kata_sandi, peran) VALUES
('Administrator Rotama Jaya', 'admin', 'admin123', 'admin');

