-- =====================================================
-- MIGRASI — Tabel log_aktivitas (audit trail admin)
-- Jalankan blok ini kalau database sudah ada sebelumnya dan belum
-- punya tabel log_aktivitas. Aman dijalankan berkali-kali karena
-- pakai IF NOT EXISTS.
-- =====================================================
CREATE TABLE IF NOT EXISTS log_aktivitas (
    id_log INT AUTO_INCREMENT PRIMARY KEY,
    id_admin INT NULL,
    nama_admin_saat_itu VARCHAR(100) NOT NULL,
    modul VARCHAR(30) NOT NULL,
    aksi VARCHAR(30) NOT NULL,
    keterangan TEXT NOT NULL,
    dicatat_pada DATETIME DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (id_admin) REFERENCES admin(id_admin) ON DELETE SET NULL,
    INDEX (dicatat_pada),
    INDEX (modul)
);

